import React, { useState, useEffect } from "react";
import { useAuth } from "../context/AuthContext";
import api from "../utils/api";
import toast from "react-hot-toast";

const DAYS = ["Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"];
const TYPES = { lecture:"#3b82f6", lab:"#10b981", tutorial:"#f59e0b" };
const inp = { width:"100%", padding:"9px 12px", background:"var(--bg3)", border:"1px solid var(--border)", borderRadius:8, color:"var(--text)", fontSize:13, outline:"none" };

export default function Timetable() {
  const { user } = useAuth();
  const [tt, setTt] = useState(null);
  const [loading, setLoading] = useState(true);
  const [semester, setSemester] = useState(user?.semester || 1);
  const [branch, setBranch] = useState(user?.branch || "CSE");
  const [showForm, setShowForm] = useState(false);
  const [newSlot, setNewSlot] = useState({ day:"Monday", startTime:"09:00", endTime:"10:00", subject:"", teacher:"", room:"", type:"lecture" });
  const [slots, setSlots] = useState([]);

  const canEdit = user?.role === "admin" || user?.role === "teacher";

  const load = () => {
    setLoading(true);
    api.get(`/timetable?semester=${semester}&branch=${branch}`)
      .then(r => { setTt(r.data); setSlots(r.data?.slots || []); })
      .catch(()=>setSlots([]))
      .finally(()=>setLoading(false));
  };

  useEffect(() => { load(); }, [semester, branch]);

  const saveSlot = () => {
    if (!newSlot.subject) return toast.error("Subject is required");
    const updated = [...slots, { ...newSlot, _id: Date.now().toString() }];
    api.post("/timetable", { semester, branch, slots: updated })
      .then(r => { setSlots(r.data.slots); setShowForm(false); toast.success("Slot added!"); })
      .catch(() => toast.error("Failed to save"));
  };

  const removeSlot = (id) => {
    const updated = slots.filter(s => s._id !== id);
    api.post("/timetable", { semester, branch, slots: updated })
      .then(r => { setSlots(r.data.slots); toast.success("Removed"); })
      .catch(() => toast.error("Failed"));
  };

  const daySlots = (day) => slots.filter(s => s.day === day).sort((a,b) => a.startTime.localeCompare(b.startTime));

  return (
    <div style={{ padding:24, maxWidth:1100, margin:"0 auto" }} className="fade-in">
      {/* Header */}
      <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:20, flexWrap:"wrap", gap:12 }}>
        <div>
          <h1 style={{ fontSize:20, fontWeight:700 }}>Timetable</h1>
          <p style={{ color:"var(--text2)", fontSize:13, marginTop:3 }}>Class schedule for {branch} Sem {semester}</p>
        </div>
        <div style={{ display:"flex", gap:10, alignItems:"center", flexWrap:"wrap" }}>
          <select value={branch} onChange={e=>setBranch(e.target.value)} style={{ ...inp, width:"auto" }}>
            {["BCA","O Level","A Level","CHE-T O-Level","PMKVY","CCC"].map(b=><option key={b}>{b}</option>)}
          </select>
          <select value={semester} onChange={e=>setSemester(+e.target.value)} style={{ ...inp, width:"auto" }}>
            {[1,2,3,4,5,6,7,8].map(s=><option key={s} value={s}>Sem {s}</option>)}
          </select>
          {canEdit && (
            <button onClick={()=>setShowForm(true)} style={{ padding:"9px 16px", borderRadius:8, background:"linear-gradient(135deg,#3b82f6,#6366f1)", border:"none", color:"#fff", fontWeight:600, fontSize:13, cursor:"pointer" }}>
              + Add Slot
            </button>
          )}
        </div>
      </div>

      {/* Add Slot Modal */}
      {showForm && (
        <div style={{ position:"fixed", inset:0, background:"rgba(0,0,0,0.6)", display:"flex", alignItems:"center", justifyContent:"center", zIndex:50 }}>
          <div style={{ background:"var(--card)", border:"1px solid var(--border)", borderRadius:16, padding:24, width:400, maxWidth:"90vw" }}>
            <h2 style={{ fontWeight:600, fontSize:16, marginBottom:16 }}>Add Slot</h2>
            <div style={{ display:"flex", flexDirection:"column", gap:11 }}>
              {[["Subject","subject","text"],["Teacher","teacher","text"],["Room","room","text"]].map(([lbl,key,type])=>(
                <div key={key}>
                  <label style={{ fontSize:11, color:"var(--text2)", display:"block", marginBottom:4 }}>{lbl}</label>
                  <input style={inp} type={type} value={newSlot[key]} onChange={e=>setNewSlot(p=>({...p,[key]:e.target.value}))} />
                </div>
              ))}
              <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:10 }}>
                <div>
                  <label style={{ fontSize:11, color:"var(--text2)", display:"block", marginBottom:4 }}>Day</label>
                  <select style={inp} value={newSlot.day} onChange={e=>setNewSlot(p=>({...p,day:e.target.value}))}>
                    {DAYS.map(d=><option key={d}>{d}</option>)}
                  </select>
                </div>
                <div>
                  <label style={{ fontSize:11, color:"var(--text2)", display:"block", marginBottom:4 }}>Type</label>
                  <select style={inp} value={newSlot.type} onChange={e=>setNewSlot(p=>({...p,type:e.target.value}))}>
                    {["lecture","lab","tutorial"].map(t=><option key={t}>{t}</option>)}
                  </select>
                </div>
                <div>
                  <label style={{ fontSize:11, color:"var(--text2)", display:"block", marginBottom:4 }}>Start</label>
                  <input style={inp} type="time" value={newSlot.startTime} onChange={e=>setNewSlot(p=>({...p,startTime:e.target.value}))} />
                </div>
                <div>
                  <label style={{ fontSize:11, color:"var(--text2)", display:"block", marginBottom:4 }}>End</label>
                  <input style={inp} type="time" value={newSlot.endTime} onChange={e=>setNewSlot(p=>({...p,endTime:e.target.value}))} />
                </div>
              </div>
            </div>
            <div style={{ display:"flex", gap:10, marginTop:18 }}>
              <button onClick={()=>setShowForm(false)} style={{ flex:1, padding:"10px", borderRadius:8, background:"var(--bg3)", border:"1px solid var(--border)", color:"var(--text)", cursor:"pointer" }}>Cancel</button>
              <button onClick={saveSlot} style={{ flex:1, padding:"10px", borderRadius:8, background:"linear-gradient(135deg,#3b82f6,#6366f1)", border:"none", color:"#fff", fontWeight:600, cursor:"pointer" }}>Save</button>
            </div>
          </div>
        </div>
      )}

      {/* Grid */}
      {loading ? <p style={{ color:"var(--text3)", fontSize:13 }}>Loading...</p> : (
        <div style={{ display:"grid", gridTemplateColumns:"repeat(auto-fit,minmax(160px,1fr))", gap:14 }}>
          {DAYS.map(day => (
            <div key={day} style={{ background:"var(--card)", border:"1px solid var(--border)", borderRadius:12, overflow:"hidden" }}>
              <div style={{ padding:"10px 14px", borderBottom:"1px solid var(--border)", fontWeight:600, fontSize:13 }}>{day}</div>
              <div style={{ padding:10, display:"flex", flexDirection:"column", gap:8, minHeight:80 }}>
                {daySlots(day).length === 0 && <p style={{ color:"var(--text3)", fontSize:12, textAlign:"center", padding:"12px 0" }}>Free</p>}
                {daySlots(day).map(slot => (
                  <div key={slot._id} style={{ background:"var(--bg3)", borderRadius:8, padding:"8px 10px", borderLeft:`3px solid ${TYPES[slot.type]||"#8b5cf6"}`, position:"relative" }}>
                    <div style={{ fontSize:12, fontWeight:600 }}>{slot.subject}</div>
                    <div style={{ fontSize:11, color:"var(--text2)", marginTop:2 }}>{slot.startTime} – {slot.endTime}</div>
                    {slot.teacher && <div style={{ fontSize:11, color:"var(--text3)" }}>{slot.teacher}</div>}
                    {slot.room && <div style={{ fontSize:11, color:"var(--text3)" }}>Room: {slot.room}</div>}
                    <span style={{ fontSize:10, background:TYPES[slot.type]+"22", color:TYPES[slot.type], padding:"1px 6px", borderRadius:10, display:"inline-block", marginTop:4 }}>{slot.type}</span>
                    {canEdit && (
                      <button onClick={()=>removeSlot(slot._id)} style={{ position:"absolute", top:6, right:6, background:"none", border:"none", color:"var(--text3)", cursor:"pointer", fontSize:14 }}>×</button>
                    )}
                  </div>
                ))}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
